func clamp(v, max int) int {
	if v > max {
		return max
	}
	return v
}

var indoMonths = []string{"", "Januari", "Februari", "Maret", "April", "Mei", "Juni", "Juli", "Agustus", "September", "Oktober", "November", "Desember"}

func indoDate(t time.Time) string {
	return fmt.Sprintf("%d %s %d", t.Day(), indoMonths[int(t.Month())], t.Year())
}

func getNotifGroups(notifs []models.Notif) []notifGroup {
	// Bandingkan tanggal wall-clock: created_at tersimpan sebagai jam Jakarta
	// (walau terbaca berlabel UTC), jadi Format memberi tanggal yang benar.
	todayStr := time.Now().Format("2006-01-02")
	yesterdayStr := time.Now().AddDate(0, 0, -1).Format("2006-01-02")

	groups := []notifGroup{}
	idx := map[string]int{}
	for _, n := range notifs {
		var label string
		switch n.Timestamp.Format("2006-01-02") {
		case todayStr:
			label = "Today"
		case yesterdayStr:
			label = "Yesterday"
		default:
			label = indoDate(n.Timestamp)
		}
		if i, ok := idx[label]; ok {
			groups[i].Notifs = append(groups[i].Notifs, n)
		} else {
			idx[label] = len(groups)
			groups = append(groups, notifGroup{label, []models.Notif{n}})
		}
	}
	return groups
}

